{"copy":"<div class="demo demo-native"><p class="demo-kicker">Approach / Out of the box</p><h1>{% if request.params.mode == 'create' %}New account{% else %}Account workspace{% endif %}</h1><p class="demo-lead">Native basic forms and the related Contacts subgrid. Contact actions open standard Power Pages modals.</p><nav class="demo-pathways" aria-label="Implementation"><a href="/approach/out-of-the-box/" aria-current="page">Out of the box</a><a href="/approach/web-api/">Web API</a><a href="/approach/pcf/">PCF</a></nav>{{ snippets['Demo/Access guidance'] }}<div class="demo-actions" style="margin-bottom:24px"><a class="demo-button secondary" href="/approach/out-of-the-box/">Back to accounts</a>{% if request.params.id %}<a class="demo-button" href="?id={{ request.params.id | escape }}&amp;mode=edit">Edit account</a><a class="demo-button secondary" href="?id={{ request.params.id | escape }}&amp;mode=read">Read-only view</a>{% endif %}</div>{% if request.params.mode == 'create' %}{% entityform name: 'Account Create' %}{% elsif request.params.mode == 'edit' %}{% entityform name: 'Account Edit' %}{% else %}{% entityform name: 'Account Read' %}{% endif %}</div>","hiddenfromsitemap":true,"isroot":false,"pagetemplateid":"b4700000-0000-4000-8000-2546863c3d7d","parentpageid":"b4700000-0000-4000-8000-2887756c2bd6","partialurl":"account","publishingstateid":"b4700000-0000-4000-8000-73c49e548d0c","rootwebpageid":"b4700000-0000-4000-8000-309d83826d44","sharedpageconfiguration":false,"title":"Native account","customcss":"/* Preserve the native Power Pages list, form, lookups and modal behavior. */
.demo-native .entitylist,.demo-native .entity-form,.demo-native .crmEntityFormView{background:#fff;border:1px solid var(--demo-border);padding:24px;border-radius:5px}.demo-native .entity-grid .view-toolbar{border:0;margin-bottom:20px}.demo-native .entity-grid .view-toolbar .view-select{font-weight:600}.demo-native .btn-primary,.demo-native input[type=submit]{background:var(--demo-forest);border-color:var(--demo-forest);color:white;border-radius:4px;padding:10px 18px}.demo-native .crmEntityFormView .tab-title{font-size:22px}.demo-native .crmEntityFormView .section-title{font-size:17px;padding:14px 0;margin-bottom:16px}.demo-native .crmEntityFormView table.section{border-spacing:18px 12px;border-collapse:separate}.demo-native .crmEntityFormView table.section td.cell{padding:10px 0}.demo-native .crmEntityFormView .control input,.demo-native .crmEntityFormView .control select{min-height:43px}.demo-native .entity-grid table td{padding:16px 12px}
.demo-native [data-native-row-count],.demo-native .demo-description-count{font-size:12px;color:var(--demo-muted);margin:10px 0}
","customjavascript":""}
